('8f500000-0000-4000-8000-000000000001','Webinar 1: Why Project Management and Contracts Management Must Work Together','webinar-01-pm-contracts-together','The PCMO philosophy of integrated project and contract delivery.','Learn why projects fail when delivery and contract management operate in silos, how an integrated delivery model connects controls and obligations, and which capabilities define the future PM-CM professional.','webinar','Project Management Fundamentals',JSON_ARRAY('free resource','webinar','video','PM-CM integration'),'PCMO Webinars','published',NOW(),JSON_OBJECT('video_url','/webinars/series-1/01-pm-and-contracts-together.mp4','duration_seconds',113,'series','Project Management Fundamentals'),JSON_ARRAY(JSON_OBJECT('name','Webinar 01 - PM and Contracts Together.mp4','url','/webinars/series-1/01-pm-and-contracts-together.mp4','download_url','/webinars/series-1/01-pm-and-contracts-together.mp4','mimeType','video/mp4')),JSON_OBJECT('featured',true),JSON_OBJECT('library',true,'membership',JSON_ARRAY('free','paid')),FALSE,0,'USD','Narrated MP4 webinar',1,90),
('8f500000-0000-4000-8000-000000000002','Webinar 2: The Complete Project Lifecycle Explained','webinar-02-complete-project-lifecycle','A beginner-friendly guide to the complete project lifecycle.','Understand initiation, planning, execution, monitoring and control, and closeout through the decisions, controls, records, responsibilities, and outputs required at each stage.','webinar','Project Management Fundamentals',JSON_ARRAY('free resource','webinar','video','project lifecycle'),'PCMO Webinars','published',NOW(),JSON_OBJECT('video_url','/webinars/series-1/02-complete-project-lifecycle.mp4','duration_seconds',118,'series','Project Management Fundamentals'),JSON_ARRAY(JSON_OBJECT('name','Webinar 02 - Complete Project Lifecycle.mp4','url','/webinars/series-1/02-complete-project-lifecycle.mp4','download_url','/webinars/series-1/02-complete-project-lifecycle.mp4','mimeType','video/mp4')),JSON_OBJECT('recommended',true),JSON_OBJECT('library',true,'membership',JSON_ARRAY('free','paid')),FALSE,0,'USD','Narrated MP4 webinar',1,89),
